import { useState } from "react";

export interface Produto {
  id: number;
  nome: string;
  preco: number;
}

interface Item {
  produto: Produto;
  quantidade: number;
}

export function useCarrinho() {
  const [itens, setItens] = useState<Item[]>([]);

  function adicionar(produto: Produto) {
    setItens((atual) => {
      const existe = atual.find((i) => i.produto.id === produto.id);
      if (existe) {
        // ja esta no carrinho: soma 1 na quantidade
        return atual.map((i) =>
          i.produto.id === produto.id
            ? { ...i, quantidade: i.quantidade + 1 }
            : i
        );
      }
      return [...atual, { produto, quantidade: 1 }];
    });
  }

  function remover(id: number) {
    setItens((atual) => atual.filter((i) => i.produto.id !== id));
  }

  function alterarQuantidade(id: number, quantidade: number) {
    if (quantidade <= 0) {
      remover(id);
      return;
    }
    setItens((atual) =>
      atual.map((i) => (i.produto.id === id ? { ...i, quantidade } : i))
    );
  }

  function limpar() {
    setItens([]);
  }

  // calculados a partir do estado: nao precisam de useState
  const totalItens = itens.reduce((soma, i) => soma + i.quantidade, 0);
  const valorTotal = itens.reduce(
    (soma, i) => soma + i.produto.preco * i.quantidade,
    0
  );

  return {
    itens,
    adicionar,
    remover,
    alterarQuantidade,
    limpar,
    totalItens,
    valorTotal,
  };
}

