// src/Cadastro.tsx
import { useState } from "react";

interface Dados {
  nome: string;
  email: string;
  cidade: string;
  cep: string;
}

type Erros = Partial<Record<keyof Dados, string>>;

export default function Cadastro() {
  const [etapa, setEtapa] = useState(1);
  const [dados, setDados] = useState<Dados>({
    nome: "",
    email: "",
    cidade: "",
    cep: "",
  });
  const [erros, setErros] = useState<Erros>({});
  const [enviado, setEnviado] = useState(false);

  function campo(nome: keyof Dados, valor: string) {
    setDados({ ...dados, [nome]: valor });
  }

  // valida so os campos da etapa atual
  function validarEtapa(): boolean {
    const novos: Erros = {};
    if (etapa === 1) {
      if (dados.nome.trim().length < 3) novos.nome = "Minimo de 3 letras";
      if (!dados.email.includes("@")) novos.email = "E-mail invalido";
    }
    if (etapa === 2) {
      if (!dados.cidade.trim()) novos.cidade = "Informe a cidade";
      if (!/^\d{5}-?\d{3}$/.test(dados.cep)) novos.cep = "CEP invalido";
    }
    setErros(novos);
    return Object.keys(novos).length === 0;
  }

  function avancar() {
    if (validarEtapa()) setEtapa(etapa + 1);
  }

  if (enviado) return <p>Cadastro concluido, {dados.nome}!</p>;

  return (
    <form
      onSubmit={(e) => {
        e.preventDefault();
        setEnviado(true);
      }}
    >
      <p>Etapa {etapa} de 3</p>

      {etapa === 1 && (
        <>
          <input
            placeholder="Nome"
            value={dados.nome}
            onChange={(e) => campo("nome", e.target.value)}
          />
          {erros.nome && <span>{erros.nome}</span>}
          <input
            placeholder="E-mail"
            value={dados.email}
            onChange={(e) => campo("email", e.target.value)}
          />
          {erros.email && <span>{erros.email}</span>}
        </>
      )}

      {etapa === 2 && (
        <>
          <input
            placeholder="Cidade"
            value={dados.cidade}
            onChange={(e) => campo("cidade", e.target.value)}
          />
          {erros.cidade && <span>{erros.cidade}</span>}
          <input
            placeholder="CEP"
            value={dados.cep}
            onChange={(e) => campo("cep", e.target.value)}
          />
          {erros.cep && <span>{erros.cep}</span>}
        </>
      )}

      {etapa === 3 && (
        <ul>
          <li>Nome: {dados.nome}</li>
          <li>E-mail: {dados.email}</li>
          <li>Cidade: {dados.cidade}</li>
          <li>CEP: {dados.cep}</li>
        </ul>
      )}

      {etapa > 1 && (
        <button type="button" onClick={() => setEtapa(etapa - 1)}>
          Voltar
        </button>
      )}
      {etapa < 3 && (
        <button type="button" onClick={avancar}>
          Avancar
        </button>
      )}
      {etapa === 3 && <button type="submit">Confirmar</button>}
    </form>
  );
}

// src/useFetch.ts
import { useState, useEffect, useRef } from "react";

// cache simples: a resposta de cada URL e a hora em que chegou
const cache = new Map<string, { dados: unknown; hora: number }>();
const VALIDADE = 60_000;   // 60 segundos, em milissegundos

export type ErroFetch =
  | { tipo: "http"; status: number }
  | { tipo: "rede"; mensagem: string };

export function useFetch<T>(url: string) {
  const [dados, setDados] = useState<T | null>(null);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState<ErroFetch | null>(null);
  const [pedido, setPedido] = useState(0);   // muda a cada refetch
  const ignorarCache = useRef(false);

  useEffect(() => {
    const controle = new AbortController();

    async function carregar() {
      const guardado = cache.get(url);
      const recente = guardado && Date.now() - guardado.hora < VALIDADE;
      if (recente && !ignorarCache.current) {
        setDados(guardado.dados as T);   // usa o cache, sem buscar
        setCarregando(false);
        return;
      }
      ignorarCache.current = false;
      setCarregando(true);
      setErro(null);
      try {
        const res = await fetch(url, { signal: controle.signal });
        if (!res.ok) {
          setErro({ tipo: "http", status: res.status });
          return;
        }
        const json = (await res.json()) as T;
        cache.set(url, { dados: json, hora: Date.now() });
        setDados(json);
      } catch (e) {
        if (controle.signal.aborted) return;
        const mensagem = e instanceof Error ? e.message : "Falha de rede";
        setErro({ tipo: "rede", mensagem });
      } finally {
        if (!controle.signal.aborted) setCarregando(false);
      }
    }

    carregar();
    return () => controle.abort();
  }, [url, pedido]);

  // busca de novo, ignorando o cache
  function refetch() {
    ignorarCache.current = true;
    setPedido((n) => n + 1);
  }

  return { dados, carregando, erro, refetch };
}

