import { notFound } from "next/navigation";

interface Produto {
  id: number;
  title: string;
  price: number;
  description: string;
  image: string;
}

export default async function Produto({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const res = await fetch(`https://fakestoreapi.com/products/${id}`, {
    next: { revalidate: 3600 },
  });
  // esta API responde 200 com o corpo vazio quando o id nao existe
  const texto = res.ok ? await res.text() : "";
  if (!texto) notFound();
  const produto: Produto = JSON.parse(texto);

  return (
    <main>
      <h1>{produto.title}</h1>
      <img src={produto.image} alt={produto.title} width={200} />
      <p>{produto.description}</p>
      <p>US$ {produto.price.toFixed(2)}</p>
    </main>
  );
}

