"use server";

import { readFile, writeFile } from "fs/promises";

export interface Resultado {
  ok: boolean;
  mensagem: string;
  valores?: { nome: string; email: string; texto: string };
}

export async function enviarMensagem(
  anterior: Resultado | null,
  formData: FormData
): Promise<Resultado> {
  const valores = {
    nome: String(formData.get("nome") ?? "").trim(),
    email: String(formData.get("email") ?? "").trim(),
    texto: String(formData.get("texto") ?? "").trim(),
  };

  // validacao no servidor; em caso de erro, devolve o que foi digitado
  if (valores.nome.length < 3) {
    return { ok: false, mensagem: "Informe o nome (minimo de 3 letras).", valores };
  }
  if (!valores.email.includes("@")) {
